from pathlib import Path
import hashlib,json,shutil,re
orig=Path('.j1-terminal-decoder/geometry');lean=Path('docs/research/100bit-spend-path-20261013/lean')
dst=lean/'extracted-terminal-decoder-20261016/AspisR1TerminalDecoder';dst.mkdir(parents=True,exist_ok=True)
for n in ('Types.lean','Funs.lean'):shutil.copy2(orig/n,dst/n)
compat=(lean/'extracted-adapter-reconstruct-20261016/AspisR1AdapterReconstruct/FunsExternal.lean').read_text().replace('AspisR1AdapterReconstruct','AspisR1TerminalDecoder').replace('Exact adapter extraction-a LLBC (171b46ec...4ad2c1d), type 7:','Exact decoder renamed LLBC (11a42d22...d13da2c), type 20:')
(dst/'FunsExternal.lean').write_text(compat)
funcs=[x for x in re.findall(r'\bdef\s+([\w.]+)',(orig/'Funs.lean').read_text()) if ('decode' in x or x.endswith('M31.from_le_bytes')) and '.closure' not in x and not x.endswith('.body')]
assert len(funcs)==15
for f in ['Types.lean','Funs.lean']:assert b'Slice.Insts.CoreCmpPartialEqArray.eq' not in (orig/f).read_bytes()
audit=lean/'TerminalDecoderGeneratedAudit.lean';audit.write_text('import AspisR1TerminalDecoder.Funs\n\n'+''.join('#print axioms AspisR1TerminalDecoder.'+f+'\n' for f in funcs))
proof=Path('.j1-terminal-decoder/geometry-proofs');(proof/'sources').mkdir(parents=True,exist_ok=True)
m={'format':2,'modules':{},'topological_order':[],'groups':{}}
for name,path,imports,count in [('AspisR1TerminalDecoder.Types',dst/'Types.lean',['Aeneas'],0),('AspisR1TerminalDecoder.FunsExternal',dst/'FunsExternal.lean',['Aeneas','AspisR1TerminalDecoder.Types'],2),('AspisR1TerminalDecoder.Funs',dst/'Funs.lean',['Aeneas','AspisR1TerminalDecoder.Types','AspisR1TerminalDecoder.FunsExternal'],0),('TerminalDecoderGeneratedAudit',audit,['AspisR1TerminalDecoder.Funs'],15)]:
 rel=name.replace('.','/')+'.lean';stage=proof/'sources'/rel;stage.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(path,stage)
 m['modules'][name]={'source':str(path),'source_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'source_revision':'72a288c2cf7745c27d1777159215116c22a63f91','imports':imports,'stage_as':rel,'role':'Unchanged decoder emission or scoped builtin tag/audit companion; no decoder correctness claim','axiom_requests':count};m['topological_order'].append(name)
(proof/'sources/SOURCE-MANIFEST.json').write_text(json.dumps(m,indent=2)+'\n')
shutil.copy2('.j1-adapter-reconstruct/proofs/runner.py',proof/'runner.py')
print('Four focused targets; fifteen actual decoder/primitive axiom requests; generated bytes unchanged')
